// ─── data/updates.js — everything What's New shows ──────────────────────────
// What's New used to be a changelog of this website and nothing else: one
// flat list, kept in pages/WhatsNew.jsx, reached from the bottom of a
// dropdown. On 2026-10-03 it became the site's news page, because there was
// finally news that was not about the site — the first rashguard samples
// being worn — and nowhere to put it.
//
// So every entry now has a `kind`:
//
//   mat    news from training, with photographs. Has a `slug` and a `story`,
//          and gets a page of its own at /whats-new/<slug>.
//   range  a change to what the shop shows.
//   site   a change to this website — the old changelog, kept as a plain log.
//
// Newest first. `id` is what the unread dot remembers, so it has to be
// unique: the older entries use their date, which is what browsers that have
// already visited have stored; anything sharing a date with another entry
// carries a suffix.
//
// Everything here is five-language text read with t(obj, lang), the same as
// the rest of the site. The entries from before 2026-10-03 were moved from
// pages/WhatsNew.jsx word for word.

import { T } from "../i18n";
import { RASHGUARD_DESIGN } from "./rashguards";

/** public/ assets, so they go through PUBLIC_URL like the shop images. */
const NEWS = `${process.env.PUBLIC_URL}/whats-new/`;
const SHOP = `${process.env.PUBLIC_URL}/shop/tshirts/`;

/** Order of the filter pills and of the sections on the page. */
export const KINDS = ["mat", "range", "site"];

const LANGS = ["en", "fr", "ja", "pt", "ro"];
const each = (fn) => Object.fromEntries(LANGS.map((l) => [l, fn(l)]));

export function formatDate(iso, lang, dateStyle = "medium") {
  return new Intl.DateTimeFormat(lang === "pt" ? "pt-BR" : lang, { dateStyle }).format(new Date(iso));
}

